      frontmatter:
        'প্রতিটি ফাইলের শীর্ষে থাকা কাঠামোগত তথ্য — ধরন, শিরোনাম, লেবেল। প্রতিটি ধারণা কী সম্পর্কে তা জানতে সহকারী এটি ব্যবহার করে।',
